async (page) => {
  const K = 'hulrqt6spvhx6';
  await page.unrouteAll();
  await page.route('**/*', async route => {
    const h = { ...route.request().headers() };
    h['baggage'] = (h['baggage'] ? h['baggage'] + ',' : '') + 'sd-routing-key=' + K;
    h['tracestate'] = 'sd-routing-key=' + K;
    await route.continue({ headers: h });
  });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const opts = await page.getByRole('combobox').first().locator('option').evaluateAll(os => os.map(o => [o.value, o.textContent]));
  await page.getByRole('combobox').first().selectOption('1');
  await page.getByRole('combobox').nth(1).selectOption('123');
  const disabled = await page.getByRole('button', { name: 'Request Ride' }).isDisabled();
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.getByRole('button', { name: 'Show Logs' }).click();
  await page.waitForTimeout(12000);
  const body = await page.locator('body').innerText();
  await page.screenshot({ path: '/tmp/ui-after.png' });
  return { opts, disabledBeforeClick: disabled, bodyLen: (await page.content()).length, errors, body };
}

